import{_ as i,c as o,h as l,b as r,i as t,e as s,w as n,j as p,a as d}from"./app-DuwZQ5pu.js";const h="/assets/img/MachineLearning/Voyager4.jpg",g={};function u(m,e){const a=p("font");return d(),o("div",null,[e[9]||(e[9]=l('<img src="'+h+'" style="display:block;margin:0 auto;"><link rel="stylesheet" href="/css/font-style.css"><h1 id="new-stage" tabindex="-1"><a class="header-anchor" href="#new-stage"><span>New Stage</span></a></h1><p> 终于，第一场比赛落下帷幕了...虽然最终排名还没出，但是 440 在现在来看算是较高的分数，省前几名应该不是问题...但这都不重要。我最近在思考一些事情，这些事情关乎未来规划和个人。</p><h2 id="职业——来龙去脉" tabindex="-1"><a class="header-anchor" href="#职业——来龙去脉"><span>职业——来龙去脉</span></a></h2><h3 id="起因" tabindex="-1"><a class="header-anchor" href="#起因"><span>起因</span></a></h3><p> 事实上，我在很早之前十分向往进入职场工作，甚至一度诞生过自己创办公司的念头...但是现实是我可能需要掌握一部分的沟通技能，了解一些财经类的知识，还有与人沟通、善辩的本领等等，这是我不太具备的东西。我曾经和我的室友一起共过事，但是由于一些纠纷原因，我选择了退出。一部分原因来自隐瞒，一部分来自技术前瞻性的分歧（对于 AI 生成长时间的视频/特效的可行性）。还有就是一些人/事（我？不懂业务？！），我可能不适合作为沟通交流的 leader，而是本职技术人员（从此创业的激情也就打消了不少）...但好在我没忘记我曾经的这些念想。</p><p> 我曾经认为喜欢一家公司可以那么的令人振奋、那么令人向往，可现实是我不理解我曾经的热爱变成它索取消费和制造各种节奏的资本，我开始抛弃曾经的那份热情，和那份热情带来的周围一切，甚至包括朋友。后来的结果很明显，我基本不再游玩游戏，有时候一个月不登一回...因为我一想到曾经经历过的喜爱遭到忽视就感觉心灰意冷，后来甚至有直接抛弃进入大城市的打算...我会觉得那很累，因为喜爱很累，尤其是当它变得不值钱的时候......</p><p> 我说的这家公司很出名，甚至我曾经就是混迹其中的一员，认识一些很厉害的大佬（有计科转美工的，有南开实习的，还有一部分外部Bot开发者，后来观察发现他也在魔理沙的群里）。当时我还在高二，我很庆幸能认识他们，但同样感到一些格格不入（因为Bot开发者仅限成年），甚至后来社区相关功能关闭，我感到心灰意冷，官方各种装死、游戏问题冷处理...这已经不是我认识的这家公司了，直到最后公司联合创始人离职卸任，我觉得这家公司变了，真的没有必要再继续坚持下去了。</p><h3 id="转折" tabindex="-1"><a class="header-anchor" href="#转折"><span>转折</span></a></h3><p> 我需要一个跳板，这个跳板能够帮助我踏入更高的地方。但这个跳板是什么？是经历么？是技术么？是领导力么？都不是，我们看一下那些周围的例子吧...比赛领队的一个老师是东大本科，华为工作一年后选择考研浙大上岸的前辈，我在思考为什么他选择不继续留在大城市，而是选择留在高校做老师呢？老师本人的回答大致是：“当年年轻，要适当出去闯一闯，看一看。但是现在近 30 了，我可能更需要的是稳定”。那么这个跳板是什么？是年轻的时候最不缺的东西，是热情和勇气、以及一丝丝对未来的恐惧和期待。我现在再回想当时老师送我们回学校路上的对话，我就感觉有另一番体会。是啊，趁着年轻多去闯闯，我还有试错的成本，那为什么要选择唾弃呢？还是陷入之前的漩涡里无法自拔选择彻底摆烂？答案是显而易见的。</p>',11)),r("p",null,[e[4]||(e[4]=t(" 再者，我们比较这部分内容。我曾经想过很多不必要的焦虑，比如")),s(a,{class:"gradient-title"},{default:n(()=>e[0]||(e[0]=[t("“找不到工作怎么办？工资低怎么办？遇到挫折，压力大怎么办？”")])),_:1,__:[0]}),e[5]||(e[5]=t("这种，那还能怎么办？面对呗，那还能咋？就像谈恋爱，你考虑")),s(a,{class:"gradient-title"},{default:n(()=>e[1]||(e[1]=[t("“他/她到底爱不爱我？到时候分手了怎么办？会伤心、闹矛盾怎么办？”")])),_:1,__:[1]}),e[6]||(e[6]=t("。不要考虑！学着放眼当下，过去是你的垫脚石，未来是你的景愿图。现在来看，我为什么在感情对话上像是白痴，因为从不考虑计较得失。当然，凡事皆有二律（背反），此消彼长，我们不能说不计较得失是好事，但也不能说全是坏事。所以，我会在")),s(a,{class:"strong"},{default:n(()=>e[2]||(e[2]=[t("谈论这些情况时陷入沉默状态，因为谈论这些毫无结果可言，每个人都有各执己见的看法，主观性大于客观性")])),_:1,__:[2]}),e[7]||(e[7]=t("。那么，我们该怎么做呢？看自己，当你觉得我需要因为一件事达成一个目标做某些事时，先问问自己")),s(a,{class:"gradient-title"},{default:n(()=>e[3]||(e[3]=[t("“你觉得这么做对你能带来多大益处？多大坏处？结果是什么？过程又有什么？”")])),_:1,__:[3]}),e[8]||(e[8]=t("。这套公式近乎能涵盖很多东西（但这会体现的极其自我...你或许也可以带入群体，看看是否合理。不过，群体的奉献往往需要牺牲自我，不要指望群体能带来可控性，群体是不稳定的）"))]),e[10]||(e[10]=l('<p> 所以我的跳板是有的，现在我们需要进一步进行阐明。我的所作皆利于我，并尽可能趋于群体有利化。但我的 MBTI 告诉我，我是个内心烂漫的人。当遇到真心喜欢的人会毫不掩盖的偏向群体有利化而忽视自我利益。但有时在学业/事业和感情上我也会做到无缝切换，这就导致于，反差出现了...我在工作的时候很讨厌别人打搅我，如果是陌生人会直接直白发言，但如果是喜欢的人...抱歉，我不修无情道。</p><h2 id="关于学业——这是纸张-不是证明" tabindex="-1"><a class="header-anchor" href="#关于学业——这是纸张-不是证明"><span>关于学业——这是纸张，不是证明</span></a></h2><h3 id="抛弃什么" tabindex="-1"><a class="header-anchor" href="#抛弃什么"><span>抛弃什么？</span></a></h3><p> 很多人会一巴掌拍在“我脸上”告诉我“学历很重要”，事实也确实是如此。但是我始终不会忘记今天和过去的我摒弃的形式化主义侵蚀（包括一纸文凭、奖状奖章）。那位“有趣的小朋友”在小红书推给我的视频里说的正有在下的影子，那个创作型人格和资本家人格在不断打架，一边是纯粹的学识、真理，一边是金钱、名誉声誉...显然，创作型人格目前仍在占据大头，但是撑不了多久了...我希望我能在以后始终坚信内心那份纯粹，事实上我也一直是如此，在不断挣扎不断妥协，不断继续前进，就像在泥土里一样...</p><p> 我需要的是一纸文凭么？不是，但我比任何人都需要一纸文凭（笑，我这里说的不是那张纸，而是指平台），我们暂且不假设什么如果，一个出身较低的人想通过自己努力不断向上爬，他要做的首先就是抛弃他的理想道德，因为理想和道德是社会化群体约束的必要（感谢小红书的那个视频，素材来了），当你抛弃了它们，你就会发现这个世界是开放世界 online 版。</p><h3 id="得到什么" tabindex="-1"><a class="header-anchor" href="#得到什么"><span>得到什么？</span></a></h3><p> 当你拥有了权力、地位和金钱，你才真正有资格谈论道德和理想。不然你以为马斯克是怎么敢这么说大话的？当你选择丢弃上述的东西时，你将得到新的东西，这就是现在你所鄙夷的。哦，该死，我们似乎达成了一个圈！当你得到了这些“肮脏的”东西后，你又会厌倦它们，想起曾经的理想、曾经的道德，你依然要回到孩童时期，回到曾经的那个自己中去...写到这里我似乎更加理解了当时读查所提到的轮回观点“你此刻正在经历的生活，将无限次地、以完全相同的细节重复上演。”，以及这部分“永恒轮回不是为了制造绝望，而是为了提供一个最强烈的生命激励。它将生命的意义从虚无缥缈的‘彼岸’或‘未来’拉了回来，聚焦于每一个当下”。我当然会有所感染，我会选择潜藏这份纯真到潜意识里，当我在某一刻有十足的念头：“我要回去！”，那么我将再次回到这部分，这部分纯真...但现在不是，我甚至一次轮回也没有完成！我要去体会和体验！</p><h2 id="ai-省流" tabindex="-1"><a class="header-anchor" href="#ai-省流"><span>AI 省流</span></a></h2><p> 这篇文章是作者在一场比赛后（获得440分，预估省前几名）对自身职业路径、学业价值与内心冲突的深度反思，呈现出从理想主义到现实主义的认知转变，但又试图在二者间寻找平衡。</p><p> 关于职业选择——从创业幻想到技术本位</p><p> 作者曾怀有强烈的创业憧憬，甚至与室友共同创业，却因沟通障碍、技术前瞻性分歧（AI生成长视频的可行性）以及对&quot;不懂业务&quot;指责的敏感而退出。这段经历让他认清自己不适合担任需要频繁沟通协调的领导者角色，更适合专注技术本身。更深层的心理创伤来自对一家曾热爱的游戏公司（从描述推测可能是米哈游（猜的真准啊！！！可恶（的幻灭——当热爱被转化为消费筹码和社区冷漠，作者选择彻底抽离，甚至一度产生逃离大城市的念头。但一位东大本科、华为工作一年后考研浙大并留校任教的前辈改变了他的认知：年轻时的&quot;跳板&quot;并非特定的经历或技能，而是那份不怕试错的热情与勇气。这促使作者形成当下的行动哲学——所作皆趋于个人利益最大化，同时尽可能兼顾群体利益；尽管MBTI显示其内心烂漫，会在感情中偏向群体利益而忽视自我，但在工作中则保持高度专注，甚至对打扰者直言不讳。</p><p> 关于学业与价值——纸张与轮回的辩证</p><p> 作者对学历持有矛盾态度：一方面鄙夷形式主义（文凭、奖状），另一方面又清醒认识到出身较低者向上攀爬时，必须暂时搁置理想与道德——因为在一个开放世界般的现实规则中，只有当权力、地位和金钱到位后，人才真正有资格谈论道德与理想。这种撕裂被描述为&quot;创作型人格&quot;与&quot;资本家人格&quot;的持续打架。文章的结尾引用尼采的&quot;永恒轮回&quot;概念，揭示出一种深刻的生命观：人终将厌倦&quot;肮脏的&quot;世俗成就，渴望回到纯真的孩童状态，但在此之前必须完成体验与历练的轮回。作者选择将那份纯真潜藏至潜意识深处，待未来某一刻&quot;我要回去&quot;的念头十分强烈时，再重返这份初心——但现在，轮回尚未开始，体验才是当务之急。</p>',13))])}const f=i(g,[["render",u]]),w=JSON.parse('{"path":"/posts/NewStage.html","title":"New Stage","lang":"en-US","frontmatter":{"title":"New Stage","description":"New Stage","date":"2026-04-01T00:00:00.000Z","timeline":true,"head":[["meta",{"name":"keywords","content":"New Stage"}],["meta",{"name":"description","content":"New Stage"}],["meta",{"name":"author","content":"RobinElysia"}]],"category":["RobinElysia"],"tag":["碎碎念"]},"headers":[{"level":2,"title":"职业——来龙去脉","slug":"职业——来龙去脉","link":"#职业——来龙去脉","children":[{"level":3,"title":"起因","slug":"起因","link":"#起因","children":[]},{"level":3,"title":"转折","slug":"转折","link":"#转折","children":[]}]},{"level":2,"title":"关于学业——这是纸张，不是证明","slug":"关于学业——这是纸张-不是证明","link":"#关于学业——这是纸张-不是证明","children":[{"level":3,"title":"抛弃什么？","slug":"抛弃什么","link":"#抛弃什么","children":[]},{"level":3,"title":"得到什么？","slug":"得到什么","link":"#得到什么","children":[]}]},{"level":2,"title":"AI 省流","slug":"ai-省流","link":"#ai-省流","children":[]}],"git":{"updatedTime":1775995407000,"contributors":[{"name":"qwp_p","username":"","email":"qwp20060309@outlook.com","commits":2}],"changelog":[{"hash":"d2c9aa5a780987b4e5f394c3caf86fd7ac13cd21","time":1775995407000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"new post"},{"hash":"1a85f1b47329c2cc437dddd65d34b84390fef012","time":1774975480000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"new post"}]},"filePathRelative":"posts/NewStage.md","excerpt":"<img src=\\"/assets/img/MachineLearning/Voyager4.jpg\\" style=\\"display: block;margin: 0 auto;\\">\\n<link rel=\\"stylesheet\\" href=\\"/css/font-style.css\\">\\n<h1>New Stage</h1>\\n<p> 终于，第一场比赛落下帷幕了...虽然最终排名还没出，但是 440 在现在来看算是较高的分数，省前几名应该不是问题...但这都不重要。我最近在思考一些事情，这些事情关乎未来规划和个人。</p>\\n<h2>职业——来龙去脉</h2>\\n<h3>起因</h3>\\n<p> 事实上，我在很早之前十分向往进入职场工作，甚至一度诞生过自己创办公司的念头...但是现实是我可能需要掌握一部分的沟通技能，了解一些财经类的知识，还有与人沟通、善辩的本领等等，这是我不太具备的东西。我曾经和我的室友一起共过事，但是由于一些纠纷原因，我选择了退出。一部分原因来自隐瞒，一部分来自技术前瞻性的分歧（对于 AI 生成长时间的视频/特效的可行性）。还有就是一些人/事（我？不懂业务？！），我可能不适合作为沟通交流的 leader，而是本职技术人员（从此创业的激情也就打消了不少）...但好在我没忘记我曾经的这些念想。</p>"}');export{f as comp,w as data};
